class DecafTeaBrewerImpl : public TeaBrewerImpl {
};

// Holds one brewer through a base-class pointer, like the lecture's TeaBrewer.
class TeaBrewer {
public:
    TeaBrewer(TeaBrewerImpl* impl) : impl(impl) {}
    ~TeaBrewer() { delete impl; }
    void addTea(Drink& drink) { impl->addTea(drink); }
private:
    TeaBrewerImpl* impl;
};

#include "check.h"
#include "teabrewer.h"

bool probe_destroyed = false;
class Probe : public TeaBrewerImpl {   // notices whether its own destructor runs
public:
    ~Probe() { probe_destroyed = true; }
};

string brew(TeaBrewerImpl& b) { Drink d; b.addTea(d); return d.tea_type; }

int main() {
    HotSteepTeaBrewerImpl hot;
    ColdBrewTeaBrewerImpl cold;
    CHECK_EQ(brew(hot), "Hot Tea");
    CHECK_EQ(brew(cold), "Cold Brew");
    if (submitting()) {
        DecafTeaBrewerImpl decaf;
        CHECK_EQ(brew(decaf), "House Tea");
        {
            TeaBrewer station(new ColdBrewTeaBrewerImpl());
            Drink d;
            station.addTea(d);
            CHECK_EQ(d.tea_type, "Cold Brew");
        }
        { TeaBrewer station(new Probe()); }
        CHECK(probe_destroyed);   // delete through a base pointer reached the derived destructor
    }
    return check_done();
}

