#pragma once
#include <iostream>

class Speaker {
    double volume;
public:
    // Write the constructor here

    // Write the destructor here

    double getVolume() const { return volume; }
};

#include <sstream>
#include "check.h"
#include "speaker.h"

// Runs one Speaker's whole life and returns everything it printed.
std::string lifeOf(double v, double* seen) {
    std::ostringstream out;
    std::streambuf* old = std::cout.rdbuf(out.rdbuf());
    {
        Speaker s(v);
        *seen = s.getVolume();
    }
    std::cout.rdbuf(old);
    return out.str();
}

int main() {
    double seen = 0;
    CHECK_EQ(lifeOf(7, &seen), "Speaker off.\n");
    CHECK_EQ(seen, 7.0);
    if (submitting()) {
        lifeOf(0.25, &seen);
        CHECK_EQ(seen, 0.25);          // the parameter has to be a double
        lifeOf(-3.5, &seen);
        CHECK_EQ(seen, -3.5);
        std::ostringstream out;
        std::streambuf* old = std::cout.rdbuf(out.rdbuf());
        Speaker* p = new Speaker(2.5);
        std::string afterNew = out.str();
        delete p;
        std::string afterDelete = out.str();
        std::cout.rdbuf(old);
        CHECK_EQ(afterNew, "");                    // the constructor prints nothing
        CHECK_EQ(afterDelete, "Speaker off.\n");   // delete runs the destructor once
    }
    return check_done();
}

