int factorial(int n) {
    if (n < 0) return -1;
    if (n == 0) return 1;
    return n * factorial(n - 1);
}

int sumDigits(int n) {
    if (n == 0) return 0;
    return n % 10 + sumDigits(n / 10);
}

int fibonacci(int n) {
    if (n == 0 || n == 1) return 1;
    return fibonacci(n - 1) + fibonacci(n - 2);
}

int fibonacciCounted(int n, vector<int>& calls) {
    calls[n]++;
    if (n == 0 || n == 1) return 1;
    return fibonacciCounted(n - 1, calls) + fibonacciCounted(n - 2, calls);
}

long long fibonacciMemo(int n, vector<long long>& memo) {
    if (n == 0 || n == 1) return 1;
    if (memo[n] != -1) return memo[n];
    memo[n] = fibonacciMemo(n - 1, memo) + fibonacciMemo(n - 2, memo);
