#pragma once
#include <vector>
using std::vector;

enum State { EMPTY, OCCUPIED, DELETED };

struct HashTable {
    vector<int> keys, values;
    vector<State> state;
    HashTable(int m) : keys(m), values(m), state(m, EMPTY) {}
    int capacity() const { return keys.size(); }
};

// ---- done in earlier lessons ----

int* find(HashTable& t, int k) {
    int m = t.capacity();
    for (int i = 0, b = k % m; i < m; i++, b = (b + 1) % m) {
        if (t.state[b] == EMPTY) return nullptr;
        if (t.state[b] == OCCUPIED && t.keys[b] == k) return &t.values[b];
    }
    return nullptr;
}

// ---- this lesson ----

bool insert(HashTable& t, int k, int v) {
    // TODO
    return false;
}

#include "check.h"
#include "probe.h"

// test helpers: where k sits (or -1), and k's value through your find (or -1)
int slotOf(const HashTable& t, int k) {
    for (int b = 0; b < t.capacity(); b++)
        if (t.state[b] == OCCUPIED && t.keys[b] == k) return b;
    return -1;
}
int copies(const HashTable& t, int k) {
    int c = 0;
    for (int b = 0; b < t.capacity(); b++) c += t.state[b] == OCCUPIED && t.keys[b] == k;
    return c;
}
int valueOf(HashTable& t, int k) {
    int* v = find(t, k);
    return v ? *v : -1;
}
void put(HashTable& t, int b, int k, int v) { t.keys[b] = k; t.values[b] = v; t.state[b] = OCCUPIED; }

int main() {
    must_finish(3, "every probe loop must give up after m probes");
    HashTable t(10);
    for (int k : {23, 43, 13, 27, 37, 16, 19, 53}) CHECK(insert(t, k, k * 10));
    CHECK_EQ(slotOf(t, 13), 5);
    CHECK_EQ(slotOf(t, 37), 8);
    CHECK_EQ(slotOf(t, 53), 0);        // wrapped
    CHECK_EQ(valueOf(t, 53), 530);
    if (submitting()) {
        CHECK(insert(t, 13, 7));       // present: replace
        CHECK_EQ(valueOf(t, 13), 7);
        CHECK_EQ(copies(t, 13), 1);
        CHECK(insert(t, 2, 20));
        CHECK_EQ(slotOf(t, 2), 2);
        CHECK(insert(t, 63, 630));
        CHECK_EQ(slotOf(t, 63), 1);
        CHECK(!insert(t, 73, 730));    // full
        CHECK(find(t, 73) == nullptr);
        CHECK(insert(t, 19, 1));       // full, but present
        CHECK_EQ(valueOf(t, 19), 1);
        HashTable z(4);
        CHECK(insert(z, 0, 5));        // key 0 is a real key
        CHECK_EQ(slotOf(z, 0), 0);
        CHECK(insert(z, 4, 6));
        CHECK_EQ(slotOf(z, 4), 1);
        CHECK_EQ(valueOf(z, 0), 5);
    }
    must_finish(0);
    return check_done();
}

