        while (*p) p = k < (*p)->info ? &(*p)->left : &(*p)->right;
        *p = N(k);
    }
    return t;
}

int main() {
    TreeNode* t = nullptr;
    for (int k : {50, 30, 70, 20, 40, 60, 80}) insert(t, k);
    CHECK_EQ(shape(t), vector<int>({50, 30, 20, 40, 70, 60, 80}));
    insert(t, 65);
    CHECK_EQ(shape(t), vector<int>({50, 30, 20, 40, 70, 60, 65, 80}));
    if (submitting()) {
        insert(t, 60);                       // duplicate: nothing changes
        insert(t, 50);
        CHECK_EQ(shape(t), vector<int>({50, 30, 20, 40, 70, 60, 65, 80}));
        TreeNode* u = N(33, N(21, N(10), N(28)), N(49, N(39, N(34)), N(65, nullptr, N(80))));
        insert(u, 50);                       // the lecture's example
        CHECK_EQ(shape(u), vector<int>({33, 21, 10, 28, 49, 39, 34, 65, 50, 80}));
        insert(u, 30);
        CHECK_EQ(shape(u), vector<int>({33, 21, 10, 28, 30, 49, 39, 34, 65, 50, 80}));
        TreeNode* s = nullptr;
        for (int k : {1, 2, 3, 4, 5}) insert(s, k);   // sorted input: a chain to the right
        CHECK(s != nullptr && s->left == nullptr);
        CHECK_EQ(shape(s), vector<int>({1, 2, 3, 4, 5}));
        TreeNode* d = nullptr;
        for (int k : {5, 4, 3}) insert(d, k);
        CHECK_EQ(shape(d), vector<int>({5, 4, 3}));
        CHECK(d != nullptr && d->right == nullptr);
        freeTree(u); freeTree(s); freeTree(d);
    }
    freeTree(t);
    return check_done();
}

