    vector<vector<int>> A(n, vector<int>(n, 0));
    for (auto [u, v] : edges) {
        A[u][v] += 1;
        A[v][u] += 1;
    }
    return A;
}

int degree(const vector<vector<int>>& A, int u) {
    int d = 0;
    for (int x : A[u]) d += x;
    return d;
}

vector<vector<int>> toList(int n, const vector<pair<int, int>>& edges, bool directed) {
    vector<vector<int>> adj(n);
    for (auto [u, v] : edges) {
        adj[u].push_back(v);
        if (!directed) adj[v].push_back(u);
    }
    return adj;
}

void dfs(const vector<vector<int>>& adj, int v, vector<bool>& visited, vector<int>& order) {
    visited[v] = true;
    order.push_back(v);
    for (int w : adj[v])
        if (!visited[w]) dfs(adj, w, visited, order);
}

vector<int> dfsOrder(const vector<vector<int>>& adj, int s) {
    vector<bool> visited(adj.size(), false);
    vector<int> order;
    dfs(adj, s, visited, order);
    return order;
}

vector<int> dfsAll(const vector<vector<int>>& adj) {
    vector<bool> visited(adj.size(), false);
    vector<int> order;
    for (int v = 0; v < (int)adj.size(); v++)
        if (!visited[v]) dfs(adj, v, visited, order);
    return order;
}

int countPieces(const vector<vector<int>>& adj) {
    vector<bool> visited(adj.size(), false);
    vector<int> order;
    int pieces = 0;
    for (int v = 0; v < (int)adj.size(); v++)
        if (!visited[v]) {
            dfs(adj, v, visited, order);
            pieces++;
        }
    return pieces;
}

